// v16.xx (perf1), the cloud review (2026-10-15, finding 30): the marks of the flow were built twice a frame, once for the minimap and once for
// the sector map, each building the lists of the fires, the events, the strongholds again. They are built once per raid time and kept
// (G.flowMk): the raid time stands still while the frame is drawn twice, and the state the marks read stands still with it.
function flowMarks(){
  var out=[];
  if(!G||!G.flow) return out;
  if(G.flowMk&&G.flowMk.t===(G.t||0)) return G.flowMk.out;

// FLOW-MARKS (the next flow builds add their marks above this line)
G.flowMk={t:G.t||0,out:out};
return out;

