{v:'VER',what:'the cloud review (finding 30): the flow marks are built once for a raid time, so the minimap and the sector map in one frame share one list',
 run:function(){
   if(!window.__deploy||!window.__endRaid||typeof flowMarks!=='function'||typeof fireMarks!=='function') return 'SKIP: no flow marks here';
   var bad=[], g, n=0, oF=fireMarks, a, b, c;
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     try{ careerPostBuild(g); }catch(_c){}
     if(!g.flow) g.flow={};
     delete g.flowMk;
     fireMarks=function(out){ n++; return oF.apply(this,arguments); };
     try{ g.t=77; a=flowMarks(); b=flowMarks(); g.t=78; c=flowMarks(); } finally { fireMarks=oF; }
     if(n!==2) bad.push('the marks were built '+n+' times for two raid times, not 2');
     if(a!==b) bad.push('two calls in one raid time did not share one list');
     if(a===c) bad.push('the list was not rebuilt for a later raid time');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ fireMarks=oF; try{ var g2=__state(); if(g2&&!g2.over){ g2.career=0; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
